package com.hiresense.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.*;
@Service public class JwtService { private final SecretKey key; private final long expiration; public JwtService(@Value("${security.jwt.secret:change-this-secret-key-to-at-least-32-bytes}") String secret,@Value("${security.jwt.expiration-ms:86400000}") long expiration){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.expiration=expiration;} public String generate(String email,Collection<String> roles){Date now=new Date();return Jwts.builder().subject(email).claim("roles",roles).issuedAt(now).expiration(new Date(now.getTime()+expiration)).signWith(key).compact();} public String subject(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();} public long expiration(){return expiration;} public boolean valid(String token){try{subject(token);return true;}catch(JwtException|IllegalArgumentException e){return false;}} }
